pub fn find_max(nums: Vec<i32>) -> i32 {
    // Since nums is guaranteed non-empty, unwrap() on the first element is safe
    let mut iter = nums.into_iter();
    let mut max_val = iter.next().unwrap();

    // Scan the rest of the elements
    for x in iter {
        if x > max_val {
            max_val = x;
        }
    }

    max_val
}

